Translate("frFR", "wailing-caverns", {
	title = "Cavernes des lamentations",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Cavernes des lamentations sont un dédale de grottes sous le cœur des {link:the-barrens}Tarides{/link}. Leur entrée s'ouvre dans une colline rocheuse près de l'{link:lushwater-oasis}Oasis luxuriante{/link}, au sud de la {link:the-crossroads}Croisée{/link}. De la vapeur jaillit des fissures de leur roche avec un long cri plaintif, et c'est de ce cri qu'elles tirent leur nom. Des rivières souterraines les parcourent sur des lieues, et de leurs sources cachées montent les eaux des nouvelles oasis. Quelque chose s'est détraqué dans les profondeurs. Les bêtes des cavernes sont devenues sauvages et étranges, l'eau porte une souillure qui se répand à travers les plaines, et les druides venus ici guérir la terre servent désormais le mal.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quel âge ont les cavernes. Ce que l'on sait, c'est que le druide {link:night-elves}elfe de la nuit{/link} {link:naralex}Naralex{/link} y vint avec une compagnie de disciples. Il voulait entrer dans le {link:emerald-dream}Rêve d'émeraude{/link} et, par sa puissance et par les sources des cavernes, faire des {link:the-barrens}Tarides{/link} desséchées la forêt qu'elles avaient été jadis. Il s'allongea pour rêver. Sa concentration faiblit, et des visions serpentines se glissèrent dans ses pensées. Son rêve devint un cauchemar, et il ne put s'éveiller. À travers son esprit endormi, le cauchemar commença à suinter dans le monde éveillé.]=],
		},
		{
			title = "De nos jours",
			text = [=[{link:naralex}Naralex{/link} dort toujours dans les profondeurs des cavernes, agité d'un sommeil troublé. La plupart de ses disciples ont été pervertis en druides du Croc, qui prennent la forme de serpents et gardent le sommeil de leur maître contre tous ceux qui voudraient y mettre fin. Leurs quatre chefs, les {link:druids-of-the-fang}seigneurs du Croc{/link}, détiennent chacun une gemme du rêve. Des raptors, des serpents et des dragons féeriques déviants sont nés du cauchemar pour hanter les tunnels, et des ectoplasmes informes dérivent dans l'obscurité.

Le monde d'en haut a commencé à s'en apercevoir. Le druide {link:tauren}tauren{/link} {link:tonga-runetotem}Tonga Runetotem{/link} a suivi la souillure des oasis jusqu'aux cavernes, et {link:hamuul-runetotem}Hamuul Runetotem{/link} a vu les druides du Croc dans ses propres rêves. {link:nara-wildmane}Nara Wildmane{/link} a appris leurs visages et veut leurs gemmes. L'apothicaire réprouvé {link:apothecary-zamah}Zamah{/link} cherche la fleur-serpent qui pousse dans les profondeurs. Les gobelins de {link:ratchet}Ratchet{/link} veulent l'essence des ectoplasmes pour leurs boissons, et un voleur surnommé Mad Magglish s'est enfui à l'intérieur avec une bouteille de vieux porto volée. Quelques disciples de Naralex restent fidèles. L'un d'eux attend dans les cavernes quiconque serait assez fort pour l'aider à réveiller son maître.]=],
		},
		{
			title = "Dans les cavernes",
			text = [=[• {b}L'entrée.{/b} Deux disciples fidèles, Nalpak et Ebru, montent la garde sur la colline au-dessus de l'entrée. La druidesse Falla Sagewind attend non loin.
• {b}Les grottes du Croc.{/b} Dans les grottes supérieures, dame {link:lady-anacondra}Anacondra{/link} et le seigneur {link:lord-cobrahn}Cobrahn{/link} commandent les druides et leurs serpents.
• {b}La rivière.{/b} Une vieille tortue, {link:kresh}Kresh{/link}, erre dans la rivière souterraine, épargnée par le cauchemar.
• {b}Les fosses profondes.{/b} Le seigneur {link:lord-pythas}Pythas{/link} et le seigneur {link:lord-serpentis}Serpentis{/link} tiennent les salles inférieures. Le lézard-tonnerre {link:skum}Skum{/link} et le gardien {link:verdan-the-everliving}Verdan l'Éternel{/link} rôdent dans les grottes lointaines.
• {b}La chambre du Rêveur.{/b} Au cœur des cavernes, {link:naralex}Naralex{/link} repose dans son sommeil agité. Sous l'eau trouble, près de lui, quelque chose attend.]=],
		},
	},
})

Translate("frFR", "naralex", {
	title = "Naralex",
	subtitle = "Le Rêveur des cavernes",
	found = "La chambre du Rêveur, au fond des Cavernes des lamentations",
	hint = [=[Cherchez le druide qui dort au cœur des Cavernes des lamentations.]=],
	allegiance = "Disciples de Naralex · Elfes de la nuit",
	sections = {
		{
			title = "Résumé",
			text = [=[Naralex est un druide {link:night-elves}elfe de la nuit{/link} venu aux {link:wailing-caverns}Cavernes des lamentations{/link} dans un noble dessein. Il croyait que, par le {link:emerald-dream}Rêve d'émeraude{/link} et par les sources cachées des cavernes, il pourrait faire refleurir les {link:the-barrens}Tarides{/link}. Il entra dans le rêve et n'en revint pas. Sa vision de renouveau devint un cauchemar, et il repose encore dans les profondeurs des cavernes, perdu entre sommeil et folie. Le cauchemar s'écoule de lui dans les eaux et dans les bêtes.]=],
		},
		{
			title = "Importance",
			text = [=[Naralex est la source de la souillure des {link:the-barrens}Tarides{/link}, et sa première victime. Ses propres disciples sont devenus ses geôliers. Tant qu'il dort, les cavernes engendrent des monstres et les oasis portent son mal à travers les plaines. Son sort est aussi un avertissement pour tous les druides d'{link:azeroth}Azeroth{/link} : le Rêve n'est pas aussi sûr qu'ils le croyaient.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena ses disciples dans les {link:wailing-caverns}Cavernes des lamentations{/link} pour guérir les {link:the-barrens}Tarides{/link}.
• Il entra dans le {link:emerald-dream}Rêve d'émeraude{/link} et fut pris au piège d'un cauchemar.
• Par ses rêves, des bêtes déviantes et des ectoplasmes entrèrent dans le monde éveillé.]=],
		},
		{
			title = "Non consigné",
			text = [=[On écrit peu ici de la vie de Naralex avant les cavernes. Cette entrée ne rapporte que ce que révèlent ses disciples et son rêve.]=],
		},
	},
	chapters = {
		{
			title = "Le cauchemar",
			hint = "Apprenez des disciples fidèles pourquoi Naralex dort.",
			text = [=[Les disciples restés fidèles racontent tous la même histoire. Leur maître aspirait à entrer dans le Rêve et à reverdir cette terre rude. Quelque chose tourna terriblement mal. Tandis que Naralex s'enfonçait dans son cauchemar, d'étranges bêtes montèrent de sous les {link:the-barrens}Tarides{/link} jusque dans les cavernes, et les druides qui l'aimaient furent changés.]=],
		},
		{
			title = "L'éveil",
			hint = [=[Protégez le disciple pendant qu'il accomplit le rite de l'éveil.]=],
			text = [=[Quand les quatre {link:druids-of-the-fang}seigneurs du Croc{/link} furent tués, le dernier disciple fidèle ouvrit la voie jusqu'à la chambre de son maître et plongea dans le Rêve pour le trouver. Des cauchemars se levèrent pour l'arrêter : des serpents, des limons, et enfin une créature monstrueuse sortie de l'eau. Quand elle tomba, Naralex s'écria qu'il était éveillé. Du corps de la bête sortit un éclat vert dans lequel une fumée semblait tourbillonner, un fragment du Rêve qui montrait un cauchemar.]=],
		},
	},
	mentions = {
		{ text = "L'éclat luisant" },
		{
			text = [=[Cauchemars, l'éclat porté à {link:thunder-bluff}Thunder Bluff{/link}]=],
		},
		{ text = "Cauchemars, l'éclat porté à {link:darnassus}Darnassus{/link}" },
	},
	bonds = {
		{ id = "disciple-of-naralex", name = "Disciple de Naralex", note = "son élève fidèle" },
		{ id = "lord-serpentis", name = "Seigneur Serpentis", note = "son élève, devenu son geôlier" },
		{ id = "mutanus-the-devourer", name = "Mutanus le Dévoreur", note = "le cauchemar qui garde son sommeil" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "a lu l'éclat de son cauchemar" },
	},
})

Translate("frFR", "disciple-of-naralex", {
	title = "Disciple de Naralex",
	subtitle = "Le dernier disciple fidèle",
	found = "L'entrée des Cavernes des lamentations",
	hint = [=[Parlez au disciple qui attend à l'entrée des Cavernes des lamentations.]=],
	allegiance = "Disciples de Naralex · Taurens",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Disciple de Naralex est un druide {link:tauren}tauren{/link}, l'un des rares fidèles de {link:naralex}Naralex{/link} que le cauchemar n'a pas pervertis. Il attend juste à l'intérieur des {link:wailing-caverns}Cavernes des lamentations{/link}. Son maître s'est rendormi, dit-il, et des bêtes reptiliennes suintent de ses rêves dans le pays. Naralex doit être tiré de son cauchemar, ou il sera perdu à jamais, et un grand mal sera libéré. Mais le Disciple ne peut accomplir le rite de l'éveil tant que ses frères corrompus vivent. Les quatre {link:druids-of-the-fang}seigneurs du Croc{/link} doivent mourir d'abord.]=],
		},
		{
			title = "Importance",
			text = [=[Le Disciple est le seul espoir du rêveur. Il connaît le rite qui peut rappeler {link:naralex}Naralex{/link}, et il a gardé la foi malgré tout ce que sont devenues les cavernes. Il en parle avec tristesse : jadis un temple de promesse pour les {link:the-barrens}Tarides{/link}, aujourd'hui des salles de cauchemar.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il bénit de la marque du fauve ceux qui veulent entrer dans les cavernes.
• Il demande la mort des quatre {link:druids-of-the-fang}seigneurs du Croc{/link}.
• Il bannit les esprits des seigneurs du Croc tués dans un cercle de feu.
• Il plonge dans le {link:emerald-dream}Rêve d'émeraude{/link} pour réveiller son maître.]=],
		},
	},
	chapters = {
		{
			title = "Le rite de l'éveil",
			hint = [=[Tuez les seigneurs du Croc, puis gardez le Disciple sur le chemin de Naralex.]=],
			text = [=[Quand les {link:druids-of-the-fang}seigneurs du Croc{/link} furent morts, le Disciple déclara que tout espoir n'était pas perdu, mais qu'il ne pouvait achever le rite seul. Il ouvrit la voie à travers les cavernes, les purifiant sur son passage, tandis que les cauchemars de son maître lançaient contre lui des vipères et pire encore. Aux côtés de {link:naralex}Naralex{/link}, il plongea dans le Rêve. Le rituel fut long, et les attaques redoublèrent, jusqu'à ce qu'enfin le rêveur s'éveille.]=],
		},
	},
	mentions = {
		{ text = "Peaux déviantes, demandées par son condisciple Nalpak" },
		{ text = "Éradication des déviants, demandée par son condisciple Ebru" },
	},
	bonds = {
		{ id = "naralex", name = "Naralex", note = "son maître" },
		{ id = "lord-serpentis", name = "Seigneur Serpentis", note = "un frère déchu" },
	},
})

Translate("frFR", "lady-anacondra", {
	title = "Dame Anacondra",
	subtitle = "Seigneur du Croc des druides du Croc",
