		},
		{
			title = "Hauts faits",
			text = [=[• Elle commande les druides et les raptors des grottes supérieures.]=],
		},
	},
	mentions = {
		{ text = "Les chefs du Croc" },
	},
	bonds = {
		{ id = "naralex", name = "Naralex", note = "son ancien maître" },
		{ id = "lord-serpentis", name = "Seigneur Serpentis", note = "dirige son ordre" },
	},
})

