	allegiance = "Druides du Croc",
	aliases = { "Verdan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Verdan l'Éternel est une immense bête des tourbières faite de plantes vivantes. On sait peu de chose de lui avant la venue de {link:naralex}Naralex{/link}. On pense qu'il était l'ancien gardien des cavernes, né de leurs profondeurs verdoyantes il y a longtemps. Le cauchemar ne l'épargna pas. Il se tient désormais avec les druides fous et écrase tout être vivant qui approche de son antre.]=],
		},
		{
			title = "Importance",
			text = [=[Verdan est le gardien même des cavernes, retourné contre la vie qu'il protégeait autrefois.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il monte la garde contre tous ceux qui s'introduisent dans les cavernes.]=],
		},
	},
	bonds = {
		{ id = "lord-serpentis", name = "Seigneur Serpentis", note = "son allié" },
	},
})

Translate("frFR", "skum", {
	title = "Skum",
	subtitle = "Le lézard-tonnerre souillé",
	found = "Les grottes lointaines des Cavernes des lamentations",
	hint = [=[Affrontez le lézard-tonnerre qui rôde dans les grottes lointaines.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Skum est un grand lézard-tonnerre des {link:the-barrens}Tarides{/link}. On dit qu'il descendit dans les cavernes pour fuir la rude terre d'en haut, en quête d'eau et d'ombre. Comme tant de créatures des grottes, il n'échappa pas à la corruption. Des énergies sombres battent désormais dans ses veines, et il est devenu une bête impitoyable que rien ne peut plus sauver.]=],
		},
		{
			title = "Importance",
			text = [=[Skum est la preuve que le cauchemar prend même les bêtes qui ne cherchent qu'un abri.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rôde parmi les grottes lointaines, où peu osent s'aventurer.]=],
		},
	},
})

Translate("frFR", "kresh", {
	title = "Kresh",
	subtitle = "La tortue épargnée",
	found = "La rivière souterraine des Cavernes des lamentations",
	hint = [=[Cherchez la vieille tortue qui nage dans la rivière souterraine.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Kresh est une tortue ancienne qui nage dans la rivière souterraine des {link:wailing-caverns}Cavernes des lamentations{/link}. Étrangement, le cauchemar ne l'a pas touchée. Tandis que tout se tord et dépérit autour d'elle, elle continue de vivre comme elle l'a toujours fait, placide et indifférente au mal qui rôde dans l'obscurité. Beaucoup ont tenté de prendre sa grande carapace. Elle l'a gardée.]=],
		},
		{
			title = "Importance",
			text = [=[Kresh est la seule créature des cavernes que le cauchemar n'a pas pu changer.]=],
		},
		{ title = "Hauts faits", text = "• Elle erre dans la rivière, épargnée par la corruption." },
	},
})

Translate("frFR", "druids-of-the-fang", {
	title = "Druides du Croc",
	aliases = { "Druide du Croc", "seigneurs du Croc", "seigneur du Croc" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les druides du Croc sont les fidèles corrompus de {link:naralex}Naralex{/link}. Ils vinrent aux {link:wailing-caverns}Cavernes des lamentations{/link} comme un ordre de nobles druides, dans le but de guérir les {link:the-barrens}Tarides{/link}. Quand le rêve de leur maître devint un cauchemar, la plupart d'entre eux tombèrent avec lui. Ils portent désormais des visages écailleux et des formes de serpents, et ils cherchent à refaire le pays à l'image de leurs propres rêves pervertis.]=],
		},
		{
			title = "L'ordre",
			text = [=[Quatre chefs les commandent, les seigneurs du Croc : dame {link:lady-anacondra}Anacondra{/link}, le seigneur {link:lord-cobrahn}Cobrahn{/link}, le seigneur {link:lord-pythas}Pythas{/link} et leur chef, le seigneur {link:lord-serpentis}Serpentis{/link}. Chacun détient une gemme du rêve. Sous eux, des druides du Croc gardent des serpents et des raptors déviants comme bêtes, et certains parcourent les plaines d'en haut. L'un d'eux, Boahn, a été vu près de la colline des cavernes. Les rares disciples qui ont gardé leur raison, parmi eux Nalpak, Ebru et le Disciple qui attend à l'intérieur, œuvrent désormais contre leurs frères déchus.]=],
		},
		{
			title = "Ce que virent les druides",
			text = [=[{link:hamuul-runetotem}Hamuul Runetotem{/link} entra dans le rêve pour apprendre ce qui empoisonnait les {link:the-barrens}Tarides{/link}. Il vit un culte de druides dont les buts avaient été nobles autrefois et qui s'étaient égarés, au service de la souillure qui suintait à travers le pays. Il était vieux et ne put rester longtemps. {link:nara-wildmane}Nara Wildmane{/link} resta, et vit leurs visages. Elle dit qu'ils la hantent encore.]=],
		},
	},
})
